import React from "react";
// PatternFly
import {
  Flex,
  FlexItem,
  PageSection,
  PaginationVariant,
  ToolbarItemVariant,
} from "@patternfly/react-core";
import {
  InnerScrollContainer,
  OuterScrollContainer,
  Td,
  Th,
  Tr,
} from "@patternfly/react-table";
// Hooks
import useUpdateRoute from "src/hooks/useUpdateRoute";
import useListPageSearchParams from "src/hooks/useListPageSearchParams";
import useApiError from "src/hooks/useApiError";
import useContextualHelpTopic from "src/hooks/useContextualHelpTopic";
import { toggleHelpPanel } from "src/store/Global/contextual-help-slice";
// Redux
import { useAppDispatch, useAppSelector } from "src/store/hooks";
// RPC
import { useDnsServersFindQuery } from "src/services/rpcDnsServers";
// React router
import { Link } from "react-router";
// Components
import ToolbarLayout, {
  ToolbarItem,
} from "src/components/layouts/ToolbarLayout";
import SearchInputLayout from "src/components/layouts/SearchInputLayout";
import SecondaryButton from "src/components/layouts/SecondaryButton";
import HelpTextWithIconLayout from "src/components/layouts/HelpTextWithIconLayout";

import PaginationLayout from "src/components/layouts/PaginationLayout";
import TitleLayout from "src/components/layouts/TitleLayout";
import GlobalErrors from "src/components/errors/GlobalErrors";
import TableLayout from "src/components/layouts/TableLayout";
import SkeletonOnTableLayout from "src/components/layouts/Skeleton/SkeletonOnTableLayout";

const DnsServers = () => {
  const dispatch = useAppDispatch();
  useContextualHelpTopic("dns-servers");

  // Contextual help panel

  // Update current route data to Redux and highlight the current page in the Nav bar
  useUpdateRoute({
    pathname: "dns-servers",
  });

  // Retrieve API version from environment data
  const apiVersion = useAppSelector(
    (state) => state.global.environment.api_version
  ) as string;

  // URL parameters: page number, page size, search value
  const { page, perPage, searchValue } = useListPageSearchParams();

  // Handle API calls errors
  const globalErrors = useApiError([]);

  // Page indexes
  const firstUserIdx = (page - 1) * perPage;
  const lastUserIdx = page * perPage;

  // States
  const [dnsServersId, setDnsServersId] = React.useState<string[]>([]);
  const [totalCount, setTotalCount] = React.useState<number>(0);

  // API calls
  const dnsServersResponse = useDnsServersFindQuery({
    searchValue,
    pkeyOnly: true,
    sizeLimit: 100,
    version: apiVersion,
  });

  const { data, isFetching, error } = dnsServersResponse;

  // Handle data when the API call is finished
  React.useEffect(() => {
    if (dnsServersResponse.isFetching) {
      setTotalCount(0);
      globalErrors.clear();
      return;
    }

    if (
      dnsServersResponse.isSuccess &&
      dnsServersResponse.data &&
      data !== undefined &&
      "data" in data
    ) {
      setTotalCount(data.data.length || 0);
      setDnsServersId(data.data.slice(firstUserIdx, lastUserIdx) || []);
    }
  }, [dnsServersResponse]);

  // Refresh button handling
  const refreshData = () => {
    setTotalCount(0);

    dnsServersResponse.refetch();
  };

  // List of Toolbar items
  const toolbarItems: ToolbarItem[] = [
    {
      key: 0,
      element: (
        <SearchInputLayout
          dataCy="search"
          name="search"
          ariaLabel="Search DNS servers"
          placeholder="Search DNS servers"
        />
      ),
      toolbarItemVariant: ToolbarItemVariant.label,
      toolbarItemGap: { default: "gapMd" },
    },
    {
      key: 1,
      toolbarItemVariant: ToolbarItemVariant.separator,
    },
    {
      key: 2,
      element: (
        <SecondaryButton
          dataCy="dns-servers-button-refresh"
          onClickHandler={refreshData}
          isDisabled={isFetching}
        >
          Refresh
        </SecondaryButton>
      ),
    },
    {
      key: 3,
      toolbarItemVariant: ToolbarItemVariant.separator,
    },
    {
      key: 4,
      element: (
        <HelpTextWithIconLayout
          textContent="Help"
          onClick={() => dispatch(toggleHelpPanel())}
        />
      ),
    },
    {
      key: 5,
      element: (
        <PaginationLayout
          list={dnsServersId}
          totalCount={totalCount}
          widgetId="pagination-options-menu-top"
          isCompact={true}
        />
      ),
      toolbarItemAlignment: { default: "alignEnd" },
    },
  ];

  // Table header
  const header = (
    <Tr key="header" id="table-header">
      <Th modifier="wrap" key="idnsserverid">
        Server name
      </Th>
    </Tr>
  );

  const body = (
    <>
      {dnsServersId.map((dnsServerId) => (
        <Tr key={`body-row-${dnsServerId}`} id={dnsServerId}>
          <Td key={`idnsserverid-${dnsServerId}`}>
            <Link to={`/dns-servers/${dnsServerId}`}>{dnsServerId}</Link>
          </Td>
        </Tr>
      ))}
    </>
  );

  const skeleton = (
    <SkeletonOnTableLayout
      rows={4}
      colSpan={9}
      screenreaderText={"Loading table rows"}
    />
  );

  // Render component
  return (
    <>
      <div>
        <PageSection hasBodyWrapper={false}>
          <TitleLayout
            id="DNS servers page"
            headingLevel="h1"
            text="DNS servers"
          />
        </PageSection>
        <PageSection hasBodyWrapper={false} isFilled={false}>
          <Flex direction={{ default: "column" }}>
            <FlexItem>
              <ToolbarLayout toolbarItems={toolbarItems} />
            </FlexItem>
            <FlexItem style={{ flex: "0 0 auto" }}>
              <OuterScrollContainer>
                <InnerScrollContainer
                  style={{ height: "55vh", overflow: "auto" }}
                >
                  {error !== undefined && error ? (
                    <GlobalErrors errors={globalErrors.getAll()} />
                  ) : (
                    <TableLayout
                      ariaLabel={"DNS servers table"}
                      variant={"compact"}
                      hasBorders={true}
                      classes={"pf-v6-u-mt-md"}
                      tableId={"dns-servers-table"}
                      isStickyHeader={true}
                      tableHeader={header}
                      tableBody={isFetching ? skeleton : body}
                    />
                  )}
                </InnerScrollContainer>
              </OuterScrollContainer>
            </FlexItem>
            <FlexItem
              style={{ flex: "0 0 auto", position: "sticky", bottom: 0 }}
            >
              <PaginationLayout
                list={dnsServersId}
                totalCount={totalCount}
                variant={PaginationVariant.bottom}
                widgetId="pagination-options-menu-bottom"
              />
            </FlexItem>
          </Flex>
        </PageSection>
      </div>
    </>
  );
};

export default DnsServers;
