import React from "react";
// PatternFly
import { PaginationVariant } from "@patternfly/react-core";
// Components
import MemberOfToolbar from "../MemberOf/MemberOfToolbar";
import MemberOfAddModal, { AvailableItems } from "../MemberOf/MemberOfAddModal";
import MemberOfDeleteModal from "../MemberOf/MemberOfDeleteModal";
import MemberTable from "src/components/tables/MembershipTable";
import PaginationLayout from "src/components/layouts/PaginationLayout";

// Data types
import { SudoCmd, SudoCmdGroup } from "src/utils/datatypes/globalDataTypes";
// Redux
import { useAppDispatch } from "src/store/hooks";
// Hooks
import { addAlert } from "src/store/Global/alerts-slice";
import useListPageSearchParams from "src/hooks/useListPageSearchParams";
import { toggleHelpPanel } from "src/store/Global/contextual-help-slice";
// Utils
import { API_VERSION_BACKUP, paginate } from "src/utils/utils";
// RPC
import { ErrorResult, MemberPayload } from "src/services/rpc";
import {
  useGetSudoCmdsInfoByNameQuery,
  useGettingSudoCmdsQuery,
} from "src/services/rpcSudoCmds";
import {
  useAddMembersToSudoCmdGroupMutation,
  useRemoveMembersFromSudoCmdGroupMutation,
} from "src/services/rpcSudoCmdGroups";
import { apiToSudoCmd } from "src/utils/sudoCmdsUtils";

interface PropsToMembersSudoGroups {
  entity: Partial<SudoCmdGroup>;
  id: string;
  from: string;
  isDataLoading: boolean;
  onRefreshData: () => void;
}

const MembersSudoCommands = (props: PropsToMembersSudoGroups) => {
  const dispatch = useAppDispatch();

  // Get parameters from URL
  const { page, setPage, perPage, searchValue } = useListPageSearchParams();

  // Other states
  const [membersSelected, setMembersSelected] = React.useState<string[]>([]);

  const memberNamesToLoad = React.useMemo(() => {
    const rawMembers = props.entity.member_sudocmd || [];
    if (rawMembers.length === 0) return [];

    let toLoad = [...rawMembers].sort();

    if (searchValue) {
      toLoad = toLoad.filter((name) =>
        name.toLowerCase().includes(searchValue.toLowerCase())
      );
    }

    return paginate(toLoad, page, perPage);
  }, [props.entity.member_sudocmd, searchValue, page, perPage]);

  // Load services
  const fullSudoCmdsQuery = useGetSudoCmdsInfoByNameQuery(
    {
      sudoCmdNamesList: memberNamesToLoad,
      no_members: true,
      version: API_VERSION_BACKUP,
    },
    {
      skip: memberNamesToLoad.length === 0 || props.isDataLoading,
      refetchOnMountOrArgChange: true, // Ensures data is always updated when the component is mounted, ignoring the cache.
    }
  );

  const members = React.useMemo(() => {
    if (!fullSudoCmdsQuery.data) return [];
    return fullSudoCmdsQuery.data.filter((m) => m.sudocmd && m.sudocmd !== "");
  }, [fullSudoCmdsQuery.data]);

  // Computed "states"
  const showTableRows = !fullSudoCmdsQuery.isFetching && !props.isDataLoading;
  const columnNames = ["Sudo command", "Description"];
  const properties = ["cn", "description"];

  // Dialogs and actions
  const [showAddModal, setShowAddModal] = React.useState(false);
  const [showDeleteModal, setShowDeleteModal] = React.useState(false);
  const [spinning, setSpinning] = React.useState(false);

  // Buttons functionality
  const isRefreshButtonEnabled =
    !fullSudoCmdsQuery.isFetching && !props.isDataLoading;
  const isAddButtonEnabled = isRefreshButtonEnabled;

  // API calls
  const [addMembers] = useAddMembersToSudoCmdGroupMutation();
  const [removeMembers] = useRemoveMembersFromSudoCmdGroupMutation();

  const [adderSearchValue, setAdderSearchValue] = React.useState("");
  const [availableCmds, setAvailableServices] = React.useState<SudoCmd[]>([]);
  const [availableItems, setAvailableItems] = React.useState<AvailableItems[]>(
    []
  );

  // Load available services, delay the search for opening the modal
  const cmdsQuery = useGettingSudoCmdsQuery({
    searchValue: adderSearchValue,
    apiVersion: API_VERSION_BACKUP,
    sizeLimit: 100,
    startIdx: 0,
    stopIdx: 100,
  });

  // Trigger available services search
  React.useEffect(() => {
    if (showAddModal) {
      cmdsQuery.refetch();
    }
  }, [showAddModal, adderSearchValue, props.entity]);

  // Update available services
  React.useEffect(() => {
    if (cmdsQuery.data && !cmdsQuery.isFetching) {
      // transform data
      const count = cmdsQuery.data.result.count;
      const results = cmdsQuery.data.result.results;
      let items: AvailableItems[] = [];
      const avalCmds: SudoCmd[] = [];
      for (let i = 0; i < count; i++) {
        const cmd = apiToSudoCmd(results[i].result);
        avalCmds.push(cmd);
        items.push({
          key: cmd.sudocmd,
          title: cmd.sudocmd,
        });
      }

      items = items.filter(
        (item) => !props.entity?.member_sudocmd?.includes(item.key)
      );

      setAvailableServices(avalCmds);
      setAvailableItems(items);
    }
  }, [cmdsQuery.data, cmdsQuery.isFetching]);

  // Add
  const onAddMember = (items: AvailableItems[]) => {
    const newMemberNames = items.map((item) => item.key);
    if (props.id === undefined || newMemberNames.length == 0) {
      return;
    }

    const payload = {
      entryName: props.id,
      entityType: "sudocmd",
      idsToAdd: newMemberNames,
    } as MemberPayload;

    setSpinning(true);
    addMembers(payload).then((response) => {
      if ("data" in response) {
        if (response.data?.result) {
          // Set alert: success
          dispatch(
            addAlert({
              name: "add-member-success",
              title: "Assigned new sudo command members to '" + props.id + "'",
              variant: "success",
            })
          );
          // Refresh data
          props.onRefreshData();
          // Close modal
          setShowAddModal(false);
        } else if (response.data?.error) {
          // Set alert: error
          const errorMessage = response.data.error as unknown as ErrorResult;
          dispatch(
            addAlert({
              name: "add-member-error",
              title: errorMessage.message,
              variant: "danger",
            })
          );
        }
      }
      setSpinning(false);
    });
  };

  // Delete
  const onDeleteMembers = () => {
    const payload = {
      entryName: props.id,
      entityType: "sudocmd",
      idsToAdd: membersSelected,
    } as MemberPayload;

    setSpinning(true);
    removeMembers(payload).then((response) => {
      if ("data" in response) {
        if (response.data?.result) {
          // Set alert: success
          dispatch(
            addAlert({
              name: "remove-members-success",
              title: "Removed sudo command members from '" + props.id + "'",
              variant: "success",
            })
          );
          // Refresh
          props.onRefreshData();
          // Disable 'remove' button
          setMembersSelected([]);
          // Close modal
          setShowDeleteModal(false);
          // Back to page 1
          setPage(1);
        } else if (response.data?.error) {
          // Set alert: error
          const errorMessage = response.data.error as unknown as ErrorResult;
          dispatch(
            addAlert({
              name: "remove-members-error",
              title: errorMessage.message,
              variant: "danger",
            })
          );
        }
      }
      setSpinning(false);
    });
  };

  return (
    <>
      <MemberOfToolbar
        searchPlaceholder="Search sudo commands"
        searchAriaLabel="Search sudo commands"
        refreshButtonEnabled={isRefreshButtonEnabled}
        onRefreshButtonClick={props.onRefreshData}
        deleteButtonEnabled={membersSelected.length > 0}
        onDeleteButtonClick={() => setShowDeleteModal(true)}
        addButtonEnabled={isAddButtonEnabled}
        onAddButtonClick={() => setShowAddModal(true)}
        helpIconEnabled={true}
        onHelpIconClick={() => dispatch(toggleHelpPanel())}
        totalItems={props.entity?.member_sudocmd?.length || 0}
      />
      <MemberTable
        entityList={members}
        idKey="sudocmd"
        from="sudo-commands"
        columnNamesToShow={columnNames}
        propertiesToShow={properties}
        checkedItems={membersSelected}
        onCheckItemsChange={setMembersSelected}
        showTableRows={showTableRows}
      />
      <PaginationLayout
        list={[]}
        totalCount={props.entity?.member_sudocmd?.length || 0}
        variant={PaginationVariant.bottom}
        widgetId="pagination-options-menu-bottom"
        className="pf-v6-u-pb-0 pf-v6-u-pr-md"
      />
      <MemberOfAddModal
        showModal={showAddModal}
        onCloseModal={() => setShowAddModal(false)}
        availableItems={availableItems}
        onAdd={onAddMember}
        onSearchTextChange={setAdderSearchValue}
        title={"Assign sudo command members to: " + props.id}
        ariaLabel={"Add sudo command members modal"}
        spinning={spinning}
      />
      <MemberOfDeleteModal
        showModal={showDeleteModal}
        onCloseModal={() => setShowDeleteModal(false)}
        title={"Delete sudo command members from: " + props.id}
        onDelete={onDeleteMembers}
        spinning={spinning}
      >
        <MemberTable
          entityList={availableCmds.filter((cmd) =>
            membersSelected.includes(cmd.sudocmd)
          )}
          from="sudo-commands"
          idKey="sudocmd"
          columnNamesToShow={columnNames}
          propertiesToShow={properties}
          showTableRows
        />
      </MemberOfDeleteModal>
    </>
  );
};

export default MembersSudoCommands;
