import React from "react";
// PatternFly
import { PaginationVariant } from "@patternfly/react-core";
// Components
import MemberOfToolbar from "../MemberOf/MemberOfToolbar";
import MemberOfAddModal, { AvailableItems } from "../MemberOf/MemberOfAddModal";
import MemberOfDeleteModal from "../MemberOf/MemberOfDeleteModal";
import MemberTable from "src/components/tables/MembershipTable";
import { MembershipDirection } from "src/components/MemberOf/MemberOfToolbar";
import PaginationLayout from "src/components/layouts/PaginationLayout";

// Data types
import { Host, HostGroup } from "src/utils/datatypes/globalDataTypes";
// Redux
import { useAppDispatch } from "src/store/hooks";
// Hooks
import { addAlert } from "src/store/Global/alerts-slice";
import useListPageSearchParams from "src/hooks/useListPageSearchParams";
import { toggleHelpPanel } from "src/store/Global/contextual-help-slice";
// Utils
import { API_VERSION_BACKUP, paginate } from "src/utils/utils";
// RPC
import { ErrorResult, MemberPayload } from "src/services/rpc";
import {
  useGetHostInfoByNameQuery,
  useGettingHostQuery,
} from "src/services/rpcHosts";
import {
  useAddAsMemberHGMutation,
  useRemoveAsMemberHGMutation,
} from "src/services/rpcHostGroups";
import {
  useAddAsMemberNGMutation,
  useRemoveAsMemberNGMutation,
} from "src/services/rpcNetgroups";
import {
  useAddAsMemberRoleMutation,
  useRemoveAsMemberRoleMutation,
} from "src/services/rpcRoles";
import { apiToHost } from "src/utils/hostUtils";

interface PropsToMembersHosts {
  entity: Partial<HostGroup>;
  id: string;
  from: string;
  isDataLoading: boolean;
  onRefreshData: () => void;
  member_host: string[];
  memberindirect_host?: string[];
  membershipDisabled?: boolean;
  setDirection: (direction: MembershipDirection) => void;
  direction: MembershipDirection;
}

const MembersHosts = (props: PropsToMembersHosts) => {
  const dispatch = useAppDispatch();

  const membershipDisabled =
    props.membershipDisabled === undefined ? false : props.membershipDisabled;

  // Get parameters from URL
  const {
    page,
    setPage,
    perPage,
    searchValue,
    membershipDirection,
    setMembershipDirection,
  } = useListPageSearchParams();

  // Other states
  const [hostsSelected, setHostsSelected] = React.useState<string[]>([]);
  const [indirectHostsSelected, setIndirectHostsSelected] = React.useState<
    string[]
  >([]);

  // Loaded hosts based on paging and member attributes
  const [hosts, setHosts] = React.useState<Host[]>([]);

  // Choose the correct entries based on the membership direction
  const member_host = props.member_host || [];
  const memberindirect_host = props.memberindirect_host || [];
  let hostNames =
    membershipDirection === "direct" ? member_host : memberindirect_host;
  hostNames = [...hostNames];

  const getHostsNameToLoad = (): string[] => {
    let toLoad = [...hostNames];
    toLoad.sort();

    // Filter by search
    if (searchValue) {
      toLoad = toLoad.filter((name) =>
        name.toLowerCase().includes(searchValue.toLowerCase())
      );
    }

    // Apply paging
    toLoad = paginate(toLoad, page, perPage);

    return toLoad;
  };

  const [hostNamesToLoad, setHostNamesToLoad] =
    React.useState<string[]>(getHostsNameToLoad());

  // Load hosts
  const fullHostsQuery = useGetHostInfoByNameQuery({
    hostNamesList: hostNamesToLoad,
    no_members: true,
    version: API_VERSION_BACKUP,
  });

  // Refresh hosts
  React.useEffect(() => {
    const hostsNames = getHostsNameToLoad();
    setHostNamesToLoad(hostsNames);
    props.setDirection(membershipDirection);
  }, [props.entity, membershipDirection, searchValue, page, perPage]);

  React.useEffect(() => {
    if (hostNamesToLoad.length > 0) {
      fullHostsQuery.refetch();
    }
  }, [hostNamesToLoad]);

  React.useEffect(() => {
    if (fullHostsQuery.data && !fullHostsQuery.isFetching) {
      setHosts(fullHostsQuery.data);
    }
  }, [fullHostsQuery.data, fullHostsQuery.isFetching]);

  // Get type of the entity to show as text
  const getEntityType = () => {
    if (props.from === "hostgroups") {
      return "host group";
    } else if (props.from === "netgroup") {
      return "netgroup";
    } else {
      // Return 'group' as default
      return "host group";
    }
  };

  // Computed "states"
  const someItemSelected = hostsSelected.length > 0;
  const showTableRows = hosts.length > 0;
  const entityType = getEntityType();
  const hostColumnNames = ["Host name", "Description"];
  const hostProperties = ["fqdn", "description"];
  const directionEnabled = props.from !== "netgroup" ? true : false;

  // Dialogs and actions
  const [showAddModal, setShowAddModal] = React.useState(false);
  const [showDeleteModal, setShowDeleteModal] = React.useState(false);
  const [spinning, setSpinning] = React.useState(false);

  // Buttons functionality
  const isRefreshButtonEnabled =
    !fullHostsQuery.isFetching && !props.isDataLoading;
  const isAddButtonEnabled =
    membershipDirection !== "indirect" && isRefreshButtonEnabled;

  // Add new member to 'Host'
  // API calls
  const [addMembersHG] = useAddAsMemberHGMutation();
  const [addMembersNG] = useAddAsMemberNGMutation();
  const [addMembersRole] = useAddAsMemberRoleMutation();
  const [removeMembersHG] = useRemoveAsMemberHGMutation();
  const [removeMembersNG] = useRemoveAsMemberNGMutation();
  const [removeMembersRole] = useRemoveAsMemberRoleMutation();

  let addMembers = addMembersHG;
  let removeMembers = removeMembersHG;
  if (props.from === "netgroup") {
    addMembers = addMembersNG;
    removeMembers = removeMembersNG;
  } else if (props.from === "roles") {
    addMembers = addMembersRole;
    removeMembers = removeMembersRole;
  }
  const [adderSearchValue, setAdderSearchValue] = React.useState("");
  const [availableHosts, setAvailableHosts] = React.useState<Host[]>([]);
  const [availableItems, setAvailableItems] = React.useState<AvailableItems[]>(
    []
  );

  // Load available hosts, delay the search for opening the modal
  const hostsQuery = useGettingHostQuery({
    searchValue: adderSearchValue,
    apiVersion: API_VERSION_BACKUP,
    sizeLimit: 100,
    startIdx: 0,
    stopIdx: 100,
  });

  // Trigger available hosts search
  React.useEffect(() => {
    if (showAddModal) {
      hostsQuery.refetch();
    }
  }, [showAddModal, adderSearchValue, props.entity]);

  // Update available hosts
  React.useEffect(() => {
    if (hostsQuery.data && !hostsQuery.isFetching) {
      // transform data
      const count = hostsQuery.data.result.count;
      const results = hostsQuery.data.result.results;
      let items: AvailableItems[] = [];
      const avalHosts: Host[] = [];
      for (let i = 0; i < count; i++) {
        const host = apiToHost(results[i].result);
        avalHosts.push(host);
        items.push({
          key: host.fqdn,
          title: host.fqdn,
        });
      }
      items = items.filter(
        (item) =>
          !member_host.includes(item.key) &&
          !memberindirect_host.includes(item.key) &&
          item.key !== props.id
      );

      setAvailableHosts(avalHosts);
      setAvailableItems(items);
    }
  }, [hostsQuery.data, hostsQuery.isFetching]);

  // Add
  const onAddHost = (items: AvailableItems[]) => {
    const newHostNames = items.map((item) => item.key);
    if (props.id === undefined || newHostNames.length == 0) {
      return;
    }

    const payload = {
      entryName: props.id,
      entityType: "host",
      idsToAdd: newHostNames,
    } as MemberPayload;

    setSpinning(true);
    addMembers(payload).then((response) => {
      if ("data" in response) {
        if (response.data?.result) {
          // Set alert: success
          dispatch(
            addAlert({
              name: "add-member-success",
              title:
                "Assigned new hosts to " + entityType + " '" + props.id + "'",
              variant: "success",
            })
          );
          // Refresh data
          props.onRefreshData();
          // Close modal
          setShowAddModal(false);
        } else if (response.data?.error) {
          // Set alert: error
          const errorMessage = response.data.error as unknown as ErrorResult;
          dispatch(
            addAlert({
              name: "add-member-error",
              title: errorMessage.message,
              variant: "danger",
            })
          );
        }
      }
      setSpinning(false);
    });
  };

  // Delete
  const onDeleteHosts = () => {
    const payload = {
      entryName: props.id,
      entityType: "host",
      idsToAdd: hostsSelected,
    } as MemberPayload;

    setSpinning(true);
    removeMembers(payload).then((response) => {
      if ("data" in response) {
        if (response.data?.result) {
          // Set alert: success
          dispatch(
            addAlert({
              name: "remove-host-success",
              title: "Removed hosts from " + entityType + " '" + props.id + "'",
              variant: "success",
            })
          );
          // Refresh
          props.onRefreshData();
          // Disable 'remove' button
          if (membershipDirection === "direct") {
            setHostsSelected([]);
          } else {
            setIndirectHostsSelected([]);
          }
          // Close modal
          setShowDeleteModal(false);
          // Back to page 1
          setPage(1);
        } else if (response.data?.error) {
          // Set alert: error
          const errorMessage = response.data.error as unknown as ErrorResult;
          dispatch(
            addAlert({
              name: "remove-hosts-error",
              title: errorMessage.message,
              variant: "danger",
            })
          );
        }
      }
      setSpinning(false);
    });
  };

  return (
    <>
      {membershipDisabled ? (
        <MemberOfToolbar
          searchPlaceholder="Search hosts"
          searchAriaLabel="Search hosts"
          refreshButtonEnabled={isRefreshButtonEnabled}
          onRefreshButtonClick={props.onRefreshData}
          deleteButtonEnabled={
            membershipDirection === "direct"
              ? hostsSelected.length > 0
              : indirectHostsSelected.length > 0
          }
          onDeleteButtonClick={() => setShowDeleteModal(true)}
          addButtonEnabled={isAddButtonEnabled}
          onAddButtonClick={() => setShowAddModal(true)}
          helpIconEnabled={true}
          onHelpIconClick={() => dispatch(toggleHelpPanel())}
          totalItems={hostNames.length}
        />
      ) : (
        <MemberOfToolbar
          searchPlaceholder="Search hosts"
          searchAriaLabel="Search hosts"
          refreshButtonEnabled={isRefreshButtonEnabled}
          onRefreshButtonClick={props.onRefreshData}
          deleteButtonEnabled={
            membershipDirection === "direct"
              ? hostsSelected.length > 0
              : indirectHostsSelected.length > 0
          }
          onDeleteButtonClick={() => setShowDeleteModal(true)}
          addButtonEnabled={isAddButtonEnabled}
          onAddButtonClick={() => setShowAddModal(true)}
          membershipDirectionEnabled={directionEnabled}
          membershipDirection={membershipDirection}
          onMembershipDirectionChange={setMembershipDirection}
          helpIconEnabled={true}
          onHelpIconClick={() => dispatch(toggleHelpPanel())}
          totalItems={hostNames.length}
        />
      )}
      <MemberTable
        entityList={hosts}
        idKey="fqdn"
        from="hosts"
        columnNamesToShow={hostColumnNames}
        propertiesToShow={hostProperties}
        checkedItems={
          membershipDirection === "direct"
            ? hostsSelected
            : indirectHostsSelected
        }
        onCheckItemsChange={
          membershipDirection === "direct"
            ? setHostsSelected
            : setIndirectHostsSelected
        }
        showTableRows={showTableRows}
      />
      <PaginationLayout
        list={[]}
        totalCount={hostNames.length}
        variant={PaginationVariant.bottom}
        widgetId="pagination-options-menu-bottom"
        className="pf-v6-u-pb-0 pf-v6-u-pr-md"
      />
      {showAddModal && (
        <MemberOfAddModal
          showModal={showAddModal}
          onCloseModal={() => setShowAddModal(false)}
          availableItems={availableItems}
          onAdd={onAddHost}
          onSearchTextChange={setAdderSearchValue}
          title={"Assign hosts to " + entityType + ": " + props.id}
          ariaLabel={"Add hosts  modal"}
          spinning={spinning}
        />
      )}
      {showDeleteModal && someItemSelected && (
        <MemberOfDeleteModal
          showModal={showDeleteModal}
          onCloseModal={() => setShowDeleteModal(false)}
          title={"Delete hosts from " + entityType + ": " + props.id}
          onDelete={onDeleteHosts}
          spinning={spinning}
        >
          <MemberTable
            entityList={availableHosts.filter((host) =>
              membershipDirection === "direct"
                ? hostsSelected.includes(host.fqdn)
                : indirectHostsSelected.includes(host.fqdn)
            )}
            from="hosts"
            idKey="fqdn"
            columnNamesToShow={hostColumnNames}
            propertiesToShow={hostProperties}
            showTableRows
          />
        </MemberOfDeleteModal>
      )}
    </>
  );
};

export default MembersHosts;
